20(20+10\cdots -k) & \equiv 0\pmod{20}
\end{align*}
Notice for any integer $k$, the left side of the congruence must be a multiple of $20$,
\begin{align*}
-17 +20(20+10\cdots -k) & \equiv 0\pmod{20}
\end{align*}
Let the number of terms, $20+10-(k+1)$ be $n$, then
\begin{align*}
n &= 20+10-(k+1)\\
&= 30 - (k+1)
\end{align*}
By definition of $n$,
\begin{align*}
-17 + 20(30 - (k+1)) & \equiv 0\pmod{20}\\
-17 + 600 -20(k+1) & \equiv 0\pmod{20}\\
-17 +600 &-20(k+1) \\
